SELECT 'tournaments' as tbl, count(*) as cnt FROM app.tournaments UNION ALL SELECT 'tournament_participants', count(*) FROM app.tournament_participants UNION ALL SELECT 'tournament_matches', count(*) FROM app.tournament_matches UNION ALL SELECT 'tournament_rewards', count(*) FROM app.tournament_rewards UNION ALL SELECT 'leagues', count(*) FROM app.leagues UNION ALL SELECT 'league_participations', count(*) FROM app.league_participations UNION ALL SELECT 'league_matches', count(*) FROM app.league_matches ORDER BY tbl;
